'use strict';
const $=(q,root=document)=>root.querySelector(q), $$=(q,root=document)=>[...root.querySelectorAll(q)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',invoices:'M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h5',gst:'M12 3l8 4v5c0 5-8 9-8 9s-8-4-8-9V7zM8 12l3 3 5-6',clients:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M20 21v-2a4 4 0 0 0-3-3.9M17 3a4 4 0 0 1 0 8',jobs:'M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',arrow:'M5 12h14M13 6l6 6-6 6',info:'M12 8v1M12 12v5M21 12a9 9 0 1 0-18 0 9 9 0 0 0 18 0',moon:'M20 15a8 8 0 0 1-11-11 9 9 0 1 0 11 11',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',plus:'M12 5v14M5 12h14',menu:'M3 6h18M3 12h18M3 18h18',close:'M6 6l12 12M6 18L18 6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.info}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const state={boot:null,tab:location.hash.slice(1)||'overview',filter:{},page:1,selected:new Set(),settingsTab:'connection',pumping:false,ledger:null,ledgerTab:'settlement',lastJobs:[],busy:false};
const canWrite=()=>state.boot?.user?.role!=='viewer',isAdmin=()=>state.boot?.user?.role==='admin';
const money=(n,c='INR')=>`${esc(c)} ${new Intl.NumberFormat(c==='INR'?'en-IN':'en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(n||0)/100)}`;
const number=n=>new Intl.NumberFormat('en-IN').format(n||0);
const tag=(s,kind)=>`<span class="tag ${kind||({Paid:'good',valid:'good',complete:'good',Unpaid:'warn',missing:'',invalid:'bad',conflict:'bad',failed:'bad',partial:'warn',running:'accent',queued:'accent',Cancelled:'',Refunded:'warn'}[s]||'')}">${esc(s)}</span>`;
const date=s=>s?esc(String(s).replace('T',' ').slice(0,19)):'—';
let toastTimer;
function toast(text,error=false){const el=$('#toast');el.textContent=text;el.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',6500);}
async function api(action,body=null,query={}){
 const opt={headers:{'Accept':'application/json'},credentials:'same-origin'};
 if(body!==null){opt.method='POST';opt.headers['Content-Type']='application/json';opt.headers['X-CSRF-Token']=state.boot?.csrf||'';opt.body=JSON.stringify(body);}
 const r=await fetch('api.php?'+new URLSearchParams({action,...query}),opt);let d;
 try{d=await r.json();}catch{throw new Error('The server did not return JSON. Check PHP extensions and the private error log.');}
 if(!r.ok){if(r.status===401){await bootstrap();}throw new Error(d.error||'Request failed.');}return d;
}
const query=(extra={})=>({...state.filter,...extra});
const link=(action,extra={})=>'api.php?'+new URLSearchParams({action,...query(extra)});
const empty=(title,body,button='')=>`<div class="empty"><div class="empty-icon">${icon('invoices')}</div><h2>${esc(title)}</h2><p>${esc(body)}</p>${button}</div>`;
const notice=(text,warn=false)=>`<div class="notice ${warn?'warn':''}">${icon('info')}<div>${text}</div></div>`;
function applyTheme(){document.documentElement.dataset.theme=localStorage.getItem('invoicedesk-theme')||'dark';if(state.boot?.preferences?.accent){const color=state.boot.preferences.accent;document.documentElement.style.setProperty('--accent',color);const c=[1,3,5].map(i=>parseInt(color.slice(i,i+2),16)/255);const l=c.map(x=>x<=.04045?x/12.92:Math.pow((x+.055)/1.055,2.4));document.documentElement.style.setProperty('--accent-ink',l[0]*.2126+l[1]*.7152+l[2]*.0722>.35?'#150c2e':'#ffffff');}}
async function bootstrap(){state.boot=await api('bootstrap');applyTheme();if(!state.filter.from){const today=state.boot.today;state.filter={from:today.slice(0,7)+'-01',to:today,basis:'date',currency:''};}if(!state.boot.user){renderAuth();return;}renderShell();await load();if(canWrite())resumeWorker();}
function renderAuth(){const install=!state.boot.installed;$('#app').innerHTML=`<main class="auth"><div class="brand"><span class="mark">iD</span><div>InvoiceDesk<small>BY HOSTINGSPELL</small></div></div><span class="eyebrow">${install?'First-time setup':'Your billing workspace'}</span><h1>${install?'Make invoices effortless.':'Welcome back.'}</h1><p class="muted">${install?'Create your private administrator account to connect WHMCS.':'Sign in to your invoice and GST workspace.'}</p>${install?notice('Copy <code>config.example.php</code> to <code>config.php</code> and set your own random setup token first.'):''}<form data-form="${install?'install':'login'}">${install?'<label>Setup token<input name="token" type="password" required autocomplete="off"><small>Matches the value you set in config.php</small></label><label>Your name<input name="name" required autocomplete="name"></label>':''}<label>Email address<input type="email" name="email" required autocomplete="username" placeholder="you@hostingspell.com"></label><label>Password<input type="password" name="password" required ${install?'minlength="12" maxlength="128"':''} autocomplete="${install?'new-password':'current-password'}"></label><div class="error-inline" role="alert"></div><button class="primary">${install?'Create administrator':'Sign in'} →</button></form><p class="fine">Private workspace · Read-only WHMCS integration · No external trackers</p></main>`;}
function renderShell(){if(!['overview','invoices','gst','clients','jobs','settings'].includes(state.tab))state.tab='overview';$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="mark">iD</span><div>InvoiceDesk<small>BY HOSTINGSPELL</small></div></div><div class="nav-label">WORKSPACE</div><nav>${[['overview','Overview'],['invoices','Invoices'],['gst','GST review'],['clients','Clients & ledgers'],['jobs','Sync & downloads'],['settings','Settings']].map(([k,v])=>`<button data-nav="${k}" class="${state.tab===k?'active':''}">${icon(k)}${v}</button>`).join('')}</nav><div class="sidebar-bottom"><small class="muted"><span class="connection-dot" style="${state.boot.configured?'':'background:var(--warn)'}"></span>${state.boot.configured?'WHMCS connected':'Connection needed'}</small><div class="identity"><div class="avatar">${esc(state.boot.user.name.slice(0,1).toUpperCase())}</div><div><strong style="font-size:12px">${esc(state.boot.user.name)}</strong><div class="muted" style="font-size:10px;text-transform:capitalize">${esc(state.boot.user.role)} workspace</div></div></div></div></aside><main class="main" id="main"><header class="topbar"><div class="actions"><button class="mobile-toggle ghost" data-do="menu" aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumb">Workspace <span style="padding:0 10px">/</span><span id="crumb"></span></div></div><div class="actions"><span id="worker-status" class="tag" hidden></span><button class="ghost small" data-do="theme" aria-label="Toggle dark and light theme">${icon('moon')}</button><button class="ghost small" data-do="logout">Sign out</button></div></header><div id="content"></div></main></div>`;}
function heading(title,sub,actions='',eyebrow='WHMCS WORKSPACE'){return `<section class="heading"><div><span class="eyebrow">${esc(eyebrow)}</span><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="actions">${actions}</div></section>`;}
function filterForm(full=false){const f=state.filter;return `<form class="filters" data-form="filter"><label>Quick range<select name="preset"><option value="custom">Custom dates</option><option value="month">This month</option><option value="last">Last month</option><option value="quarter">This quarter</option><option value="fy">Financial year</option></select></label><label class="range">From<input type="date" name="from" value="${esc(f.from)}" required></label><label class="range">To<input type="date" name="to" value="${esc(f.to)}" required></label><label>Date basis<select name="basis">${[['date','Invoice issued'],['paid','Invoice paid'],['due','Invoice due']].map(([v,t])=>`<option value="${v}" ${f.basis===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Currency<select name="currency"><option value="">All currencies</option>${(state.boot.currencies||[]).map(c=>`<option value="${esc(c.code)}" ${f.currency===c.code?'selected':''}>${esc(c.code)}</option>`).join('')}</select></label>${full?`<label>Status<select name="status"><option value="">All statuses</option>${['Paid','Unpaid','Payment Pending','Cancelled','Refunded','Draft','Collections'].map(v=>`<option ${f.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Recipient GSTIN<select name="gst"><option value="">All checks</option>${['valid','missing','invalid','conflict'].map(v=>`<option ${f.gst===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Tax charged<select name="tax"><option value="">Any</option><option value="yes" ${f.tax==='yes'?'selected':''}>Yes</option><option value="no" ${f.tax==='no'?'selected':''}>No</option></select></label><label class="search">Find invoice or client<input name="search" type="search" placeholder="Number, client, GSTIN…" value="${esc(f.search||'')}"></label>`:''}<button class="primary">Apply</button></form>`;}
async function load(){if(!state.boot?.user)return;$$('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===state.tab));$('#crumb').textContent=({overview:'Overview',invoices:'Invoices',gst:'GST review',clients:'Clients & ledgers',jobs:'Sync & downloads',settings:'Settings'})[state.tab];$('#content').innerHTML='<div class="loading">Loading workspace…</div>';try{await ({overview:overview,invoices:invoices,gst:invoices,clients:clients,jobs:jobsPage,settings:settings})[state.tab]();}catch(e){$('#content').innerHTML=notice(esc(e.message),true);}}
function spark(rows,currency){if(!rows.length)return empty('No trend yet','Sync invoices for this period to see billing by month.');const data=rows.filter(r=>r.currency===currency);if(!data.length)return '';const max=Math.max(1,...data.map(r=>Number(r.total)));const points=data.map((r,i)=>[45+(data.length===1?.5:i/(data.length-1))*470,145-Number(r.total)/max*115]);const p=points.map(x=>x.join(',')).join(' ');return `<svg class="chart" viewBox="0 0 550 190" role="img" aria-label="Monthly billed totals in ${esc(currency)}">${[30,88,145].map(y=>`<line x1="40" x2="525" y1="${y}" y2="${y}"/>`).join('')}<polygon class="area" points="${points[0][0]},145 ${p} ${points.at(-1)[0]},145"/><polyline class="line" points="${p}"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="3"><title>${esc(data[i].month)}: ${money(data[i].total,currency)}</title></circle>${i===0||i===points.length-1?`<text x="${x}" y="176" text-anchor="middle">${esc(data[i].month)}</text>`:''}`).join('')}<text x="38" y="20">${money(max,currency)}</text></svg>`;}
function bars(rows,label,value,currency=''){const max=Math.max(1,...rows.map(r=>Number(r[value])));return `<div class="bar-list">${rows.map(r=>`<div class="bar-line"><div class="meta"><span>${esc(r[label]||'Unknown')}</span><span class="mono">${currency?money(r[value],r.currency||currency):number(r[value])}</span></div><div class="bar"><i style="width:${Math.max(1,Number(r[value])/max*100)}%"></i></div></div>`).join('')}</div>`;}
async function overview(){const d=await api('dashboard',null,query());const totals=d.totals;const primary=totals.find(t=>t.currency==='INR')||totals[0];const curr=primary?.currency||state.filter.currency||'INR';const cash=d.cash.find(c=>c.currency===curr);const configured=state.boot.configured;$('#content').innerHTML=heading('A clear view of your billing.','Invoices, collections, and GST checks in one quiet workspace.',canWrite()?'<button class="primary" data-do="sync">'+icon('plus')+' Sync invoices</button>':'','BILLING OVERVIEW')+filterForm()+(!configured?notice('<strong>Connect your WHMCS to begin.</strong> Choose API or direct database mode in Settings. <a href="#settings" data-nav="settings">Set up connection →</a>'):!d.flags.all_count?notice('No cached invoices match this range. Sync the selected dates to import them.'):'')+`<div class="stats"><div class="stat"><div class="label">Billed sales ${icon('invoices')}</div><div class="value"><small>${esc(curr)}</small> ${money(primary?.billed||0,'').trim()}</div><div class="note">${number(primary?.invoices||0)} sales invoices · by selected invoice dates</div></div><div class="stat"><div class="label">Cash received ${icon('download')}</div><div class="value"><small>${esc(curr)}</small> ${money(cash?.received||0,'').trim()}</div><div class="note">Gross payments · by transaction date</div></div><div class="stat"><div class="label">Tax recorded ${icon('gst')}</div><div class="value"><small>${esc(curr)}</small> ${money(primary?.tax||0,'').trim()}</div><div class="note">WHMCS tax level 1 + level 2</div></div><div class="stat"><div class="label">Needs review ${icon('info')}</div><div class="value">${number(d.flags.review_count)}</div><div class="note">Across the filtered invoice register</div></div></div><div class="grid two"><div class="card"><div class="card-header"><div><h2>Billing over time</h2><p>Issued invoice totals · ${esc(curr)}</p></div>${tag('Sales register')}</div>${spark(d.trend,curr)}<div class="legend"><span><i></i>Billed amount</span><span>Drafts, cancellations, refunds, deposits & mass pay excluded</span></div></div><div class="card"><div class="card-header"><div><h2>Recipient GSTIN checks</h2><p>Format, checksum, and evidence</p></div><button class="ghost small" data-nav="gst">Review →</button></div>${d.gst.length?bars(d.gst,'gst_status','n'):empty('No checks yet','GSTIN findings will appear after your first sync.')}</div></div><div class="grid equal spacer"><div class="card"><div class="card-header"><div><h2>Outstanding by age</h2><p>Current cached balances · selected invoices · ${esc(curr)}</p></div></div>${d.aging.filter(x=>x.currency===curr).length?bars(d.aging.filter(x=>x.currency===curr),'bucket','amount',curr):empty('Nothing outstanding','No positive balances in this selection.')}</div><div class="card"><div class="card-header"><div><h2>Payment gateways</h2><p>Net receipts before fees · transaction dates · ${esc(curr)}</p></div></div>${d.gateways.filter(x=>x.currency===curr).length?bars(d.gateways.filter(x=>x.currency===curr),'gateway','net',curr):empty('Import payment activity','Use a payment sync to include receipts, refunds and deposits.')}</div></div>${totals.length>1?`<div class="card spacer"><h2>Currency totals</h2><p class="section-note">Currencies stay separate. Charts above show ${esc(curr)}.</p><div class="table-wrap"><table><thead><tr><th>Currency</th><th class="num">Sales billed</th><th class="num">Tax recorded</th><th class="num">Current due</th></tr></thead><tbody>${totals.map(r=>`<tr><td>${esc(r.currency)}</td><td class="num">${money(r.billed,r.currency)}</td><td class="num">${money(r.tax,r.currency)}</td><td class="num">${money(r.due,r.currency)}</td></tr>`).join('')}</tbody></table></div></div>`:''}<div class="coverage"><span>Cache updated: ${date(d.flags.newest)} · ${esc(state.boot.timezone)}</span><span>Invoice and cash scopes differ. Payment totals require a payment-journal sync.</span></div>${d.coverage.length?`<details class="spacer"><summary class="muted">Recent completed imports</summary><div class="card spacer">${d.coverage.slice(0,5).map(x=>`<div class="kv"><span>${esc(x.kind)} ${x.client_id?'· client #'+esc(x.client_id):esc(x.from_date||'')+' → '+esc(x.to_date||'')}</span><span class="muted">${date(x.completed_at)}</span></div>`).join('')}</div></details>`:''}`;}
function gstSummaryView(d){return `<div class="card flush" style="margin-bottom:22px"><div class="card-header"><div><h2>GST analysis · working summary</h2><p>All matching sales invoices before the exception-review filter. Categories describe evidence.</p></div></div>${d.recipients.length?`<div class="table-wrap"><table><thead><tr><th>Recipient evidence</th><th>Currency</th><th class="num">Invoices</th><th class="num">Subtotal</th><th class="num">Tax recorded</th><th class="num">Invoice value</th></tr></thead><tbody>${d.recipients.map(r=>`<tr><td>${esc(r.category)}</td><td>${esc(r.currency)}</td><td class="num">${number(r.invoices)}</td><td class="num">${money(r.subtotal,r.currency)}</td><td class="num">${money(r.tax,r.currency)}</td><td class="num">${money(r.total,r.currency)}</td></tr>`).join('')}</tbody></table></div><details style="padding:16px 20px"><summary>Tax rates & recipient state codes</summary><div class="grid equal spacer"><div><h3>WHMCS tax levels</h3>${d.rates.map(r=>`<div class="kv"><span class="key">${esc(r.taxrate||'0')}% + ${esc(r.taxrate2||'0')}% · ${number(r.invoices)} invoices</span><strong>${money(Number(r.tax)+Number(r.tax2),r.currency)}</strong></div>`).join('')}</div><div><h3>Recipient GSTIN state code</h3>${d.states.map(r=>`<div class="kv"><span class="key">${esc(r.state_code)} · ${esc(r.country||'Unknown country')}</span><strong>${money(r.tax,r.currency)}</strong></div>`).join('')}</div></div><p class="section-note">GSTIN state code is not a determination of place of supply. This is a reconciliation working sheet; GSTR filing, e-invoicing and registration status require separate verification.</p></details>`:empty('No tax summary for this range','Import invoices to see recipient categories, taxes, and state-code totals.')}${d.duplicates.length?`<div class="notice warn" style="margin:16px">${icon('info')}<div>Duplicate invoice numbers in this range: ${d.duplicates.map(x=>esc(x.number)+' (IDs '+esc(x.ids)+')').join('; ')}. Review numbering before export.</div></div>`:''}</div>`;}
async function invoices(){const gst=state.tab==='gst';const d=await api('invoices',null,query({page:state.page,...(gst?{review:'1'}:{})}));const taxSummary=gst?await api('gst_summary',null,query()):null;state.currentRows=d.rows;$('#content').innerHTML=heading(gst?'Give every exception a decision.':'Your invoice register.',gst?'Review missing evidence, invalid tax IDs, and accounting exceptions.':'Filter, inspect, and download exactly the invoices you need.',canWrite()?`<a class="btn" href="${link('csv',gst?{review:'1'}:{})}">${icon('download')} CSV</a><button data-do="bulk">${icon('download')} Bulk download</button><button class="primary" data-do="sync">${icon('plus')} Sync</button>`:'',gst?'GST WORKSPACE':'INVOICE WORKSPACE')+filterForm(true)+(gst?gstSummaryView(taxSummary):'')+(gst?notice('A valid GSTIN format and checksum do not confirm registration or decide tax treatment. Current profile details remain flagged until reviewed. Supplier GSTIN is excluded from recipient detection.'):'')+`<div class="card flush"><div class="card-header"><div class="actions"><h2>${number(d.total)} invoices</h2><span class="tag">${state.selected.size} selected</span></div><div class="actions">${canWrite()?'<button class="ghost small" data-do="refresh-filter">Refresh filtered invoices</button>':''}<button class="ghost small" data-do="clear-selection">Clear selection</button></div></div>${d.rows.length?`<div class="table-wrap"><table><thead><tr><th><input type="checkbox" data-do="select-page" aria-label="Select this page" ${d.rows.every(x=>state.selected.has(x.id))?'checked':''}></th><th>Invoice</th><th>Client</th><th class="num">Total / tax</th><th>Status</th><th>Recipient GSTIN</th><th>Evidence</th><th></th></tr></thead><tbody>${d.rows.map(i=>`<tr><td><input type="checkbox" data-select="${i.id}" aria-label="Select invoice ${esc(i.number)}" ${state.selected.has(i.id)?'checked':''}></td><td><strong>${esc(i.number)}</strong><div class="sub">${esc(i.date)} · #${i.id}</div></td><td><strong>${esc(i.client_name)}</strong><div class="sub">Client #${i.client_id}</div></td><td class="num">${money(i.total,i.currency)}<div class="sub">Tax ${money(Number(i.tax)+Number(i.tax2),i.currency)}</div></td><td>${tag(i.status)}<div class="sub">${i.balance>0?'Due '+money(i.balance,i.currency):''}</div></td><td>${tag(i.gst_status)}<div class="sub mono">${esc(i.gstin||'No recipient GSTIN found')}</div></td><td>${tag(i.basis==='snapshot'?'Invoice snapshot':'Current profile',i.basis==='snapshot'?'good':'warn')}<div class="sub">${i.pdf_check?'PDF: '+esc(JSON.parse(i.pdf_check).result)+' · ':''}${i.review_status==='reviewed'&&i.review_hash===i.source_hash?'✓ Reviewed':i.review?'Needs review':'No exception'}</div></td><td><button class="small" data-invoice="${i.id}">View →</button></td></tr>`).join('')}</tbody></table></div>`:empty('No invoices in this view','Adjust your filters or sync invoices from WHMCS.',canWrite()?'<button class="primary" data-do="sync">Sync invoices</button>':'')}<div class="pagination"><span>Page ${d.page} of ${Math.max(1,d.pages)} · Cached WHMCS data</span><div class="actions"><button class="small" data-page="${d.page-1}" ${d.page<=1?'disabled':''}>← Previous</button><button class="small" data-page="${d.page+1}" ${d.page>=d.pages?'disabled':''}>Next →</button></div></div></div>`;}
function modal(html){$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
const closeButton='<button class="ghost" data-do="close" aria-label="Close dialog">'+icon('close')+'</button>';
async function invoiceDetail(id){const i=await api('invoice',null,{id});state.detail=i;const payload=i.payload.invoice;const reviewed=i.review_record;modal(`<div class="heading"><div><span class="eyebrow">INVOICE #${i.id}</span><h1 id="modal-title">${esc(i.number)}</h1><p>${esc(i.client_name)} · ${tag(i.status)}</p></div><div class="actions">${canWrite()?`<a class="btn small" target="_blank" rel="noopener" href="${link('copy',{id})}">Print copy</a><a class="btn small primary" target="_blank" rel="noopener" href="${link('pdf',{id})}">Original PDF ↗</a>`:''}${closeButton}</div></div><dl class="detail-meta">${[['Invoice date',i.date],['Due date',i.due_date],['Paid date',i.paid_date||'—'],['Currency',i.currency],['Recipient GSTIN',i.gstin||'Not found'],['GSTIN check',i.gst_status],['Evidence',i.basis],['Last fetched',i.fetched_at]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="table-wrap"><table><thead><tr><th>Description</th><th>Taxed</th><th class="num">Amount</th></tr></thead><tbody>${(payload.items?.item||[]).map(x=>`<tr><td class="wrap">${esc(x.description).replace(/\n/g,'<br>')}</td><td>${x.taxed?'Yes':'No'}</td><td class="num">${esc(x.amount)}</td></tr>`).join('')}</tbody></table></div><div class="grid equal spacer"><div><h3>Checks & evidence</h3>${i.issues.length?'<ul class="issues">'+i.issues.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'<p class="muted">No automated exception found.</p>'}<p class="section-note">${payload._gst?.evidence?.map(x=>`${esc(x.source)}: ${esc(x.value)} · ${x.valid?'format + checksum pass':'check failed'}`).join('<br>')||'No recipient tax ID evidence.'}</p><a href="https://services.gst.gov.in/services/searchtp" target="_blank" rel="noopener">Open GST taxpayer search ↗</a></div><div>${[['Subtotal',i.subtotal],['Tax level 1',i.tax],['Tax level 2',i.tax2],['Total',i.total],['Credit applied',i.credit],['Balance',i.balance]].map(([k,v])=>`<div class="kv"><span class="key">${k}</span><strong>${money(v,i.currency)}</strong></div>`).join('')}</div></div><details class="spacer"><summary>Invoice transactions (${i.transactions.length})</summary><div class="table-wrap spacer"><table><thead><tr><th>Date</th><th>Gateway / reference</th><th class="num">Received</th><th class="num">Refunded</th><th class="num">Fees</th></tr></thead><tbody>${i.transactions.map(t=>`<tr><td>${date(t.date)}</td><td>${esc(t.gateway)}<div class="sub">${esc(t.reference)}</div></td><td class="num">${money(t.amount_in,t.currency)}</td><td class="num">${money(t.amount_out,t.currency)}</td><td class="num">${money(t.fees,t.currency)}</td></tr>`).join('')}</tbody></table></div></details><div class="notice spacer">${icon('info')}<div>Original PDFs use your WHMCS template. Printable copies are generated from this cache. ${i.pdf_check?`Last PDF text check: <strong>${esc(i.pdf_check.result)}</strong>${i.pdf_check.source_hash&&i.pdf_check.source_hash!==i.source_hash?' · stale since invoice data changed':''} · candidates: ${esc(i.pdf_check.recipient_candidates.join(', ')||'none')}. ${esc(i.pdf_check.note)}`:'PDF contents have not been checked.'}</div></div>${canWrite()?`<div class="actions"><button class="small" data-pdf-check="${id}">Check original PDF text</button><button class="small" data-refresh-one="${id}">Refresh from WHMCS</button></div><form class="review-form" data-form="review"><input type="hidden" name="id" value="${id}"><label>Review decision<select name="status"><option value="reviewed">Mark reviewed</option><option value="open">Keep open</option></select></label><label>Internal review note<textarea name="note" maxlength="2000" placeholder="What did you verify?">${esc(reviewed?.note||'')}</textarea></label><button class="primary">Save review</button></form>${reviewed?`<p class="section-note">Last decision: ${esc(reviewed.status)} by ${esc(reviewed.reviewer)} on ${date(reviewed.updated_at)}${reviewed.source_hash!==i.source_hash?' · SOURCE CHANGED — review is stale':''}</p>`:''}`:''}`);}
async function clients(){const d=await api('clients',null,{search:state.clientSearch||''});$('#content').innerHTML=heading('Know every client balance.','Inspect invoices, payments, refunds, and credit-wallet activity.',canWrite()?'<button class="primary" data-do="client-sync">'+icon('plus')+' Full client sync</button>':'','CLIENT WORKSPACE')+`<div class="grid equal"><div class="card"><h2>Open a client ledger</h2><p class="section-note">Use the WHMCS client ID. Run a full client sync first for complete coverage.</p><form class="inline-form" data-form="open-ledger"><label>WHMCS client ID<input name="id" type="number" min="1" required placeholder="e.g. 1234"></label><button class="primary">Open ledger →</button></form></div><div class="card"><h2>Search imported clients</h2><p class="section-note">Search by company, name, email, or client ID.</p><form class="inline-form" data-form="client-search"><label>Client search<input name="search" value="${esc(state.clientSearch||'')}" type="search" placeholder="Find a client…"></label><button>Find</button></form></div></div><div class="card flush spacer"><div class="card-header"><h2>Imported clients</h2><span class="muted">Up to 100 results</span></div>${d.rows.length?`<div class="table-wrap"><table><thead><tr><th>Client</th><th>Currency</th><th class="num">Invoices cached</th><th class="num">Credit wallet</th><th>Full ledger sync</th><th></th></tr></thead><tbody>${d.rows.map(c=>`<tr><td><strong>${esc(c.name)}</strong><div class="sub">#${c.id} · ${esc(c.email)}</div></td><td>${esc(c.currency)}</td><td class="num">${number(c.invoices)}</td><td class="num">${money(c.wallet,c.currency)}</td><td>${date(c.ledger_at)}</td><td><button class="small" data-ledger="${c.id}">Ledger →</button></td></tr>`).join('')}</tbody></table></div>`:empty('No clients imported','Sync invoice dates or import a full client ledger to populate this view.')}</div>`;}
async function openLedger(id){const d=await api('ledger',null,query({id}));state.ledger=d;state.ledgerId=id;renderLedger();}
function renderLedger(){const d=state.ledger,c=d.client,t=state.ledgerTab;modal(`<div class="heading"><div><span class="eyebrow">CLIENT #${c.id}</span><h1 id="modal-title">${esc(c.name)}</h1><p>${esc(c.email)} · ${esc(state.filter.from)} → ${esc(state.filter.to)}</p></div><div class="actions">${canWrite()?`<button class="small" data-sync-client="${c.id}">Full sync</button><a class="btn small" href="${link('ledger_csv',{id:c.id})}">Ledger CSV</a><a class="btn small" href="${link('payments_csv',{id:c.id})}">Payments CSV</a><a class="btn small" href="${link('credits_csv',{id:c.id})}">Wallet CSV</a>`:''}${closeButton}</div></div>${notice(d.note,true)}${!c.ledger_at?notice('<strong>Partial client data.</strong> Run a full client sync before relying on opening balances or totals.',true):notice('Full client sync completed '+date(c.ledger_at)+'. Changes in WHMCS since that time are not included.')}<div class="grid equal"><div class="card"><h3>Reconstructed period balance</h3>${Object.entries(d.closing).map(([currency,v])=>`<div class="kv"><span class="key">${esc(currency)} · closing</span><strong>${money(v,currency)}</strong></div><div class="kv"><span class="key">Opening</span><span>${money(d.opening[currency]||0,currency)}</span></div>`).join('')||'<p class="muted">No settlement entries.</p>'}</div><div class="card"><h3>Current source reconciliation</h3>${d.source_balances.map(x=>`<div class="kv"><span class="key">Invoice balances · ${esc(x.currency)}</span><strong>${money(x.balance,x.currency)}</strong></div>`).join('')}<div class="kv"><span class="key">Credit wallet · separate liability</span><strong>${money(c.wallet,c.currency)}</strong></div></div></div><div class="tabs spacer">${[['settlement','Settlement ledger'],['payments','All payments'],['credits','Credit wallet']].map(([v,n])=>`<button data-ledger-tab="${v}" class="${t===v?'active':''}">${n}</button>`).join('')}</div>${t==='settlement'?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Reference</th><th class="num">Debit</th><th class="num">Credit</th><th class="num">Balance</th></tr></thead><tbody>${d.rows.map(r=>`<tr><td>${date(r.date)}</td><td class="wrap">${esc(r.reference)}</td><td class="num">${r.debit?money(r.debit,r.currency):'—'}</td><td class="num">${r.credit?money(r.credit,r.currency):'—'}</td><td class="num">${money(r.balance,r.currency)}</td></tr>`).join('')}</tbody></table></div><p class="section-note">${number(d.row_count)} entries. ${d.row_count>5000?'View limited to 5,000 entries; narrow your dates.':''} Unallocated receipts and credit-wallet movements appear in their own tabs.</p>`:t==='payments'?`<div class="table-wrap"><table><thead><tr><th>Date / reference</th><th>Gateway</th><th>Invoice</th><th class="num">Received</th><th class="num">Refunded</th><th class="num">Fees</th></tr></thead><tbody>${d.payments.map(r=>`<tr><td>${date(r.date)}<div class="sub mono">${esc(r.reference)}</div></td><td>${esc(r.gateway)}</td><td>${r.invoice_id?'#'+r.invoice_id:'Unallocated'}</td><td class="num">${money(r.amount_in,r.currency)}</td><td class="num">${money(r.amount_out,r.currency)}</td><td class="num">${money(r.fees,r.currency)}</td></tr>`).join('')}</tbody></table></div>${d.payments_truncated?notice('Showing 5,000 payments. Narrow the date range.',true):''}`:`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Description</th><th class="num">Wallet movement</th></tr></thead><tbody>${d.credits.map(r=>`<tr><td>${date(r.date)}</td><td class="wrap">${esc(r.description)}</td><td class="num">${money(r.amount,c.currency)}</td></tr>`).join('')}</tbody></table></div>${d.credits_truncated?notice('Showing 5,000 credit movements. Narrow the date range.',true):''}<p class="section-note">Wallet movements are separate from cash revenue. A transfer from wallet to invoice must not be counted as another payment.</p>`}`);}
async function jobsPage(){const d=await api('jobs');state.lastJobs=d.rows;renderJobs();}
function renderJobs(){if(state.tab!=='jobs')return;$('#content').innerHTML=heading('Let the repetitive work run.','Resumable imports and bulk exports, with a clear result for every invoice.',canWrite()?'<button data-do="payment-sync">Import payment journal</button><button class="primary" data-do="sync">'+icon('plus')+' Sync invoices</button>':'','SYNC & DOWNLOADS')+notice('Browser processing runs one invoice at a time. Keep this workspace open, or add the bundled CLI worker to cPanel Cron Jobs to continue in the background. Failed records remain visible and can be retried.')+`<div class="actions" style="margin-bottom:20px">${canWrite()?'<button class="small" data-do="run-worker">Resume browser worker</button>':''}${isAdmin()?'<button class="small" data-do="hook-poll">Check WHMCS hook queue</button>':''}<button class="ghost small" data-do="reload">Refresh list</button></div><div class="card flush">${state.lastJobs.length?state.lastJobs.map(j=>`<article class="job"><div class="job-top"><div><div class="job-title"><strong>${esc(j.type==='archive'?'Bulk download':j.type==='ledger'?'Client ledger sync':j.type==='payments'?'Payment journal':j.type==='refresh'?'Invoice refresh':j.type==='pdf_scan'?'Original PDF GSTIN scan':'Invoice date sync')}</strong>${tag(j.state)}</div><p>${esc(j.message)}</p><small class="mono muted">${esc(j.id)} · ${date(j.created_at)}</small></div><div class="actions">${j.downloadable?`<a class="btn small primary" href="${link('download',{id:j.id})}">${icon('download')} ${j.state==='partial'?'Partial ZIP':'Download ZIP'}</a>`:''}${canWrite()&&['failed','partial'].includes(j.state)?`<button class="small" data-retry-job="${j.id}">Retry failed</button>`:''}${canWrite()&&['queued','running'].includes(j.state)?`<button class="small ghost" data-cancel-job="${j.id}">Cancel</button>`:''}</div></div>${j.total?`<div class="bar"><i style="width:${Math.min(100,Number(j.done)/Number(j.total)*100)}%"></i></div><small class="muted">${number(j.done)} of ${number(j.total)} complete${j.errors?' · '+number(j.errors)+' failed':''}</small>`:''}${j.failures.length?`<details class="job-errors"><summary>${number(j.errors||j.failures.length)} failed records</summary><ul>${j.failures.map(f=>`<li>${j.type==='payments'?'Client':'Invoice'} #${f.record_id}: ${esc(f.error)}</li>`).join('')}</ul></details>`:''}</article>`).join(''):empty('Your first sync starts here','Choose a date range to import invoices, or sync an entire client ledger.',canWrite()?'<button class="primary" data-do="sync">Sync invoices</button>':'')}</div>`;}
async function settings(){const tab=state.settingsTab;$('#content').innerHTML=heading('Built around your workflow.','Control connections, GST detection, access, and appearance.','','WORKSPACE SETTINGS')+`<div class="tabs">${(isAdmin()?[['connection','Connection'],['gst','GST & preferences'],['users','Team access'],['audit','Activity'],['account','My account']]:[['account','My account']]).map(([v,t])=>`<button data-settings-tab="${v}" class="${tab===v?'active':''}">${t}</button>`).join('')}</div><div id="settings-content"></div>`;if(!isAdmin())state.settingsTab='account';await renderSettings();}
async function renderSettings(){const tab=state.settingsTab;const el=$('#settings-content');if(tab==='connection'&&isAdmin()){const c=await api('connection');el.innerHTML=`<div class="grid two"><div class="card"><h2>WHMCS connection</h2><p class="section-note">One WHMCS instance per installation. You can switch modes for that same instance.</p><form data-form="connection"><div class="form-grid"><label class="full">Instance name<input name="instance" value="${esc(c.instance||'manage.hostingspell.com')}" required><small>A stable name shared by API and database modes.</small></label><label class="full">Connection mode<select name="mode" id="connection-mode"><option value="api" ${c.mode==='api'?'selected':''}>WHMCS API · remote or same server</option><option value="db" ${c.mode==='db'?'selected':''}>Direct database · SELECT only</option></select></label><div class="full form-grid" id="api-fields" ${c.mode==='db'?'hidden':''}><label class="full">WHMCS API endpoint<input type="url" name="api_url" value="${esc(c.api_url||'')}" placeholder="https://manage.hostingspell.com/includes/api.php"></label><label>API identifier<input name="identifier" value="${esc(c.identifier||'')}" autocomplete="off"></label><label>API secret<input type="password" name="secret" autocomplete="new-password" placeholder="${c.secret_set?'Saved · leave blank to retain':'Enter API secret'}"></label></div><div class="full form-grid" id="db-fields" ${c.mode!=='db'?'hidden':''}>${[['db_host','Database host',c.db_host||'localhost'],['db_port','Port',c.db_port||3306],['db_name','Database name',c.db_name||''],['db_user','SELECT-only username',c.db_user||'']].map(([n,t,v])=>`<label>${t}<input name="${n}" value="${esc(v)}"></label>`).join('')}<label class="full">Database password<input type="password" name="db_password" autocomplete="new-password" placeholder="${c.db_password_set?'Saved · leave blank to retain':'Enter database password'}"></label><label class="full">TLS CA file · remote MySQL<input name="db_ssl_ca" value="${esc(c.db_ssl_ca||'')}" placeholder="/home/account/private/mysql-ca.pem"><small>Use localhost on the same cPanel account; require TLS for remote MySQL.</small></label></div></div><hr><h3>WHMCS bridge <span class="tag">Optional</span></h3><p class="section-note">Enables original PDFs, historical snapshots, and queued hook updates in either mode.</p><div class="form-grid"><label class="full">Bridge endpoint<input type="url" name="bridge_url" value="${esc(c.bridge_url||'')}" placeholder="https://manage.hostingspell.com/invoicedesk-bridge.php"></label><label class="full">Bridge shared secret<input type="password" name="bridge_secret" autocomplete="new-password" placeholder="${c.bridge_secret_set?'Saved · leave blank to retain':'32+ random characters'}"></label></div><div class="form-actions"><button type="button" data-do="test-connection">Test connection</button><button class="primary">Test & save</button></div><div class="connection-result section-note" role="status"></div></form></div><div><div class="card"><h2>Choose the best connection</h2><div class="steps"><div class="step"><div><strong>API mode</strong><p>Use a restricted WHMCS API role with GetInvoices, GetInvoice, GetClientsDetails, GetCurrencies, GetTransactions, and GetCredits. Allow this server’s outgoing IP.</p></div></div><div class="step"><div><strong>Database mode</strong><p>Same-cPanel deployments can connect over localhost. Create a separate MySQL user with SELECT only; use your WHMCS database name.</p></div></div><div class="step"><div><strong>Add the bridge for original PDFs</strong><p>Install the bundled bridge beside WHMCS init.php, and keep its configuration and queue outside the web root. Setup steps are in the included README.</p></div></div></div></div>${notice('API invoice scans use documented pagination. Database mode uses indexed date ranges and keyset pagination. Imports cache data locally and never update WHMCS invoices.')}</div></div>`;}
else if(tab==='gst'&&isAdmin()){const p=state.boot.preferences;el.innerHTML=`<div class="card" style="max-width:820px"><h2>Detection and workspace preferences</h2><p class="section-note">Tax amounts are preserved exactly as returned by WHMCS. No automatic CGST/SGST split is inferred.</p><form data-form="preferences"><div class="form-grid"><label>Company display name<input name="company" value="${esc(p.company)}" required></label><label>Supplier GSTIN<input name="supplier_gstin" value="${esc(p.supplier_gstin)}" maxlength="15" placeholder="Your own GSTIN"><small>Excluded from recipient matching.</small></label><label class="full">Recipient GST custom field names<input name="gst_labels" value="${esc(p.gst_labels)}"><small>Comma-separated, case-insensitive exact field names. Standard WHMCS Tax ID is always checked.</small></label><label>Accent color<input name="accent" type="color" value="${esc(p.accent)}"></label><label>ZIP retention · days<input name="archive_days" type="number" min="1" max="90" value="${p.archive_days}"></label><label class="full">Client profile cache · minutes<input name="client_cache_minutes" type="number" min="0" max="60" value="${p.client_cache_minutes??5}"><small>Short cache reduces API calls. Zero fetches fresh profile details for every invoice.</small></label><label class="check full"><input name="tax_is_gst" type="checkbox" ${p.tax_is_gst?'checked':''}>Our WHMCS tax rules represent GST</label></div><p class="section-note">This adds a review flag when GST-configured tax is charged without one valid recipient GSTIN. Retail sales can still be taxable. Refresh cached invoices after changing these rules.</p><div class="form-actions"><button type="button" data-do="prune">Clean expired ZIP files</button><button class="primary">Save preferences</button></div></form></div>`;}
else if(tab==='users'&&isAdmin()){const d=await api('users');state.users=d.rows;el.innerHTML=`<div class="card flush"><div class="card-header"><div><h2>Team access</h2><p>Viewer: read · Analyst: sync, review, export · Admin: settings and users</p></div><button class="primary" data-do="new-user">Add user</button></div><div class="table-wrap"><table><thead><tr><th>Name / email</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody>${d.rows.map(u=>`<tr><td>${esc(u.name)}<div class="sub">${esc(u.email)}</div></td><td>${esc(u.role)}</td><td>${tag(u.enabled?'Active':'Disabled',u.enabled?'good':'')}</td><td><button class="small" data-user="${u.id}">Edit access</button></td></tr>`).join('')}</tbody></table></div></div>`;}
else if(tab==='audit'&&isAdmin()){const d=await api('audit');el.innerHTML=`<div class="card flush"><div class="card-header"><h2>Recent activity</h2><span class="muted">Last 150 events</span></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Details</th></tr></thead><tbody>${d.rows.map(a=>`<tr><td>${date(a.created_at)}</td><td>${esc(a.name||'System')}</td><td>${esc(a.event)}</td><td class="wrap mono">${esc(a.detail)}</td></tr>`).join('')}</tbody></table></div></div>`;}
else{el.innerHTML=`<div class="card" style="max-width:600px"><h2>My account</h2><p class="section-note">${esc(state.boot.user.email)} · ${esc(state.boot.user.role)}</p><form data-form="password"><div class="form-grid"><label class="full">Current password<input name="current" type="password" required autocomplete="current-password"></label><label class="full">New password<input name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"><small>Between 12 and 128 characters. Updating your password signs out all sessions.</small></label></div><div class="form-actions"><button class="primary">Update password</button></div></form></div>`;}}
function userModal(id=0){const u=state.users?.find(x=>x.id===id)||{id:0,name:'',email:'',role:'viewer',enabled:1};modal(`<div class="heading"><div><h1 id="modal-title">${id?'Edit access':'Add a team member'}</h1><p>Manage this workspace’s access.</p></div>${closeButton}</div><form data-form="user_save"><input type="hidden" name="id" value="${u.id}"><div class="form-grid"><label>Name<input name="name" required value="${esc(u.name)}"></label><label>Email<input name="email" type="email" required value="${esc(u.email)}"></label><label>Role<select name="role">${['viewer','analyst','admin'].map(r=>`<option ${u.role===r?'selected':''}>${r}</option>`).join('')}</select></label><label>${id?'New password · optional':'Password'}<input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" ${id?'':'required'}></label><label class="check full"><input name="enabled" type="checkbox" ${u.enabled?'checked':''}>Account enabled</label></div><div class="form-actions"><button class="primary">Save access</button></div></form>`);}
function syncModal(type='sync',clientId=''){const title=type==='ledger'?'Import a full client ledger':type==='payments'?'Import payment journal':'Sync invoices';modal(`<div class="heading"><div><span class="eyebrow">WHMCS IMPORT</span><h1 id="modal-title">${title}</h1></div>${closeButton}</div><form data-form="sync"><input name="type" type="hidden" value="${type}">${type==='ledger'?`<label>WHMCS client ID<input name="client_id" type="number" min="1" required value="${esc(clientId)}"></label><p class="section-note">Imports all invoice dates, all client payments, refunds, current wallet balance and credit history. This can take several minutes.</p>`:`<div class="form-grid"><label>From<input name="from" type="date" required value="${state.filter.from}"></label><label>To<input name="to" type="date" required value="${state.filter.to}"></label>${type==='sync'?`<label class="full">Invoice date basis<select name="basis">${[['date','Issue date'],['paid','Paid date'],['due','Due date']].map(([v,n])=>`<option value="${v}" ${state.filter.basis===v?'selected':''}>${n}</option>`).join('')}</select></label>`:''}</div><p class="section-note">${type==='payments'?'Includes unallocated deposits, receipts, refunds, and gateway fees by transaction date. API mode checks that WHMCS returns a complete result.':'Date range is inclusive. API mode scans invoice headers; database mode filters at source. Existing cache entries are refreshed.'}</p>`}<div class="form-actions"><button class="primary">Start import →</button></div></form>`);}
function bulkModal(){modal(`<div class="heading"><div><span class="eyebrow">BULK EXPORT</span><h1 id="modal-title">Download invoices together.</h1><p>Each archive includes a result manifest.</p></div>${closeButton}</div><form data-form="bulk"><div class="form-grid"><label class="full">Invoices<select name="scope"><option value="selected" ${state.selected.size?'':'disabled'}>${state.selected.size} selected invoices</option><option value="filtered" ${state.selected.size?'':'selected'}>All matching current filters · maximum 10,000</option></select></label><label class="full">Output or check<select name="format"><option value="pdf">Original WHMCS PDFs · bridge required</option><option value="html">Printable HTML copies · cache only</option><option value="scan">Scan original PDF GSTINs · bridge + pdftotext required</option></select></label></div><p class="section-note">PDFs retain the WHMCS invoice template. HTML copies can be printed or saved as PDF in your browser. ZIPs include GST checks and source timestamps in manifest.csv. PDF scans store matches and ambiguity in each invoice, also available in invoice CSV exports.</p><div class="form-actions"><button class="primary">Build ZIP archive →</button></div></form>`);}
async function createJob(type,params){const d=await api('job_create',{type,params});$('#modal').close();state.tab='jobs';location.hash='jobs';await load();startWorker(d.id);}
async function resumeWorker(){const d=await api('jobs');state.lastJobs=d.rows;const j=d.rows.find(x=>['queued','running'].includes(x.state));if(j)startWorker(j.id);}
async function startWorker(id){if(state.pumping)return;state.pumping=true;const indicator=$('#worker-status');if(indicator){indicator.hidden=false;indicator.textContent='Processing…';}try{let running=true;while(running&&state.boot?.user){const d=await api('job_tick',id?{id}:{});if(!['queued','running'].includes(d.state)){running=false;if(d.state==='complete')toast('Job completed.');else if(d.state!=='idle')toast(d.message||'Job stopped.',true);}const all=await api('jobs');state.lastJobs=all.rows;if(state.tab==='jobs')renderJobs();if(running)await new Promise(resolve=>setTimeout(resolve,700));}}catch(e){toast(e.message,true);}finally{state.pumping=false;const x=$('#worker-status');if(x)x.hidden=true;}}
function formValues(form){const v=Object.fromEntries(new FormData(form));$$('input[type=checkbox]',form).forEach(el=>v[el.name]=el.checked);return v;}
document.addEventListener('submit',async e=>{const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();if(state.busy)return;state.busy=true;const submit=$('button[type=submit],button:not([type])',f);if(submit)submit.disabled=true;const v=formValues(f),name=f.dataset.form;try{if(name==='filter'){delete v.preset;state.filter=v;state.page=1;state.selected.clear();await load();}
else if(name==='login'){const d=await api('login',v);state.boot.csrf=d.csrf;await bootstrap();}
else if(name==='install'){await api('install',v);toast('Administrator created. Sign in to connect WHMCS.');await bootstrap();}
else if(name==='sync')await createJob(v.type,v);
else if(name==='bulk')await createJob(v.format==='scan'?'pdf_scan':'archive',{format:v.format,ids:[...state.selected],all_filtered:v.scope==='filtered',filter:query(state.tab==='gst'?{review:'1'}:{})});
else if(name==='review'){await api('review',v);toast('Review saved.');await invoiceDetail(v.id);}
else if(name==='open-ledger')await openLedger(Number(v.id));
else if(name==='client-search'){state.clientSearch=v.search;await clients();}
else if(name==='connection'){const d=await api('connection_save',v);toast('WHMCS connection saved.');state.boot.configured=true;state.boot.currencies=d.currencies;$('.connection-result',f).textContent=d.message;}
else if(name==='preferences'){const d=await api('preferences',v);toast(d.note);state.boot=await api('bootstrap');applyTheme();}
else if(name==='user_save'){await api('user_save',v);$('#modal').close();toast('Team access saved.');await renderSettings();}
else if(name==='password'){await api('password',v);toast('Password updated. Sign in again.');await bootstrap();}}
catch(err){const inline=$('.error-inline',f);if(inline)inline.textContent=err.message;else toast(err.message,true);}finally{state.busy=false;if(submit)submit.disabled=false;}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='connection-mode'){$('#api-fields').hidden=el.value!=='api';$('#db-fields').hidden=el.value!=='db';}if(el.dataset.select){const id=Number(el.dataset.select);el.checked?state.selected.add(id):state.selected.delete(id);const n=$('.card-header .tag');if(n)n.textContent=state.selected.size+' selected';}if(el.name==='preset'&&el.value!=='custom'){const today=new Date(state.boot.today+'T12:00:00Z');let start=new Date(today),end=new Date(today);const year=today.getUTCFullYear(),month=today.getUTCMonth();if(el.value==='month')start=new Date(Date.UTC(year,month,1));if(el.value==='last'){start=new Date(Date.UTC(year,month-1,1));end=new Date(Date.UTC(year,month,0));}if(el.value==='quarter')start=new Date(Date.UTC(year,Math.floor(month/3)*3,1));if(el.value==='fy')start=new Date(Date.UTC(month<3?year-1:year,3,1));const f=el.closest('form');$('[name=from]',f).value=start.toISOString().slice(0,10);$('[name=to]',f).value=end.toISOString().slice(0,10);}});
document.addEventListener('click',async e=>{const el=e.target.closest('button,a,input[data-do]');if(!el)return;try{
 if(el.dataset.nav){e.preventDefault();state.tab=el.dataset.nav;state.page=1;state.selected.clear();location.hash=state.tab;$('.shell')?.classList.remove('menu-open');await load();return;}
 if(el.dataset.page){state.page=Number(el.dataset.page);await invoices();return;}
 if(el.dataset.invoice){await invoiceDetail(Number(el.dataset.invoice));return;}
 if(el.dataset.ledger){state.ledgerTab='settlement';await openLedger(Number(el.dataset.ledger));return;}
 if(el.dataset.ledgerTab){state.ledgerTab=el.dataset.ledgerTab;renderLedger();return;}
 if(el.dataset.settingsTab){state.settingsTab=el.dataset.settingsTab;await settings();return;}
 if(el.dataset.user){userModal(Number(el.dataset.user));return;}
 if(el.dataset.syncClient){syncModal('ledger',el.dataset.syncClient);return;}
 if(el.dataset.pdfCheck){el.disabled=true;const d=await api('pdf_check',{id:Number(el.dataset.pdfCheck)});toast('PDF text check: '+d.result);await invoiceDetail(Number(el.dataset.pdfCheck));return;}
 if(el.dataset.refreshOne){await createJob('refresh',{ids:[Number(el.dataset.refreshOne)]});return;}
 if(el.dataset.retryJob){await api('job_retry',{id:el.dataset.retryJob});await jobsPage();startWorker(el.dataset.retryJob);return;}
 if(el.dataset.cancelJob){await api('job_cancel',{id:el.dataset.cancelJob});await jobsPage();return;}
 const action=el.dataset.do;if(!action)return;
 if(action==='theme'){localStorage.setItem('invoicedesk-theme',document.documentElement.dataset.theme==='dark'?'light':'dark');applyTheme();}
 else if(action==='logout'){await api('logout',{});state.boot.user=null;await bootstrap();}
 else if(action==='menu')$('.shell').classList.toggle('menu-open');
 else if(action==='close')$('#modal').close();
 else if(action==='sync')syncModal();
 else if(action==='payment-sync')syncModal('payments');
 else if(action==='client-sync')syncModal('ledger');
 else if(action==='bulk')bulkModal();
 else if(action==='reload')await load();
 else if(action==='clear-selection'){state.selected.clear();await invoices();}
 else if(action==='select-page'){state.currentRows.forEach(x=>el.checked?state.selected.add(x.id):state.selected.delete(x.id));await invoices();}
 else if(action==='refresh-filter')await createJob('refresh',{all_filtered:true,filter:query(state.tab==='gst'?{review:'1'}:{})});
 else if(action==='run-worker')await resumeWorker();
 else if(action==='hook-poll'){const d=await api('bridge_poll',{});toast(d.message);await jobsPage();if(d.id)startWorker(d.id);}
 else if(action==='new-user')userModal();
 else if(action==='prune'){const d=await api('prune',{});toast(d.removed+' expired archives removed.');}
 else if(action==='test-connection'){const f=el.closest('form');el.disabled=true;const d=await api('connection_test',formValues(f));$('.connection-result',f).textContent=d.message+(d.bridge?' Bridge connected.':'');toast('Connection test passed.');}
 }catch(err){toast(err.message,true);}finally{if(el.isConnected)el.disabled=false;}});
window.addEventListener('hashchange',()=>{const tab=location.hash.slice(1);if(tab&&tab!==state.tab){state.tab=tab;state.page=1;load();}});
bootstrap().catch(e=>{$('#app').innerHTML=`<main class="auth"><h1>InvoiceDesk needs attention.</h1>${notice(esc(e.message),true)}<p class="muted">Check PHP 8.2+, PDO SQLite, OpenSSL, cURL, and your HTTPS configuration. See the deployment guide in your download.</p></main>`;});
